/* Gods SDL port: the program's variables that the host's own files (guest.c, host.c, irq.c, files.c) use.  On the desktop they are the program's symbols (the linker script guest.ld
 * gives them their addresses); in the browser build (GODS_WEB: wasm has no linker script) each is the memory at its address (guest_addr_web.h, generated by gen_guest.py). */
#ifndef GODS_SDL_GUEST_VARS_H
#define GODS_SDL_GUEST_VARS_H

#include <stdint.h>

#ifdef GODS_WEB
#include "guest_addr_web.h"
#define disk_digit (*(volatile uint8_t *)GODS_ADDR_disk_digit)
#define image_table (*(uint8_t **)GODS_ADDR_image_table)
#define asset_memory (*(uint8_t **)GODS_ADDR_asset_memory)
#define memory_base (*(uint8_t **)GODS_ADDR_memory_base)
#define shadow_table ((uint16_t *)GODS_ADDR_shadow_table)
#define heap_base (*(uint32_t *)GODS_ADDR_heap_base)
#define mask_buffer (*(uint8_t **)GODS_ADDR_mask_buffer)
#define palette_dirty (*(uint16_t *)GODS_ADDR_palette_dirty)
#define vbl_saturating (*(volatile uint16_t *)GODS_ADDR_vbl_saturating)
#define vbl_count (*(volatile uint16_t *)GODS_ADDR_vbl_count)
#define pending_request (*(volatile uint32_t *)GODS_ADDR_pending_request)
#define key_down ((volatile uint8_t *)GODS_ADDR_key_down)
#define ptr_0cc6 (*(uint8_t **)GODS_ADDR_ptr_0cc6)
#else
extern volatile uint8_t disk_digit;   /* the digit of the disk the program asks for (menu.symbols) */
extern uint8_t *image_table, *asset_memory, *memory_base;
extern uint16_t shadow_table[];
extern uint32_t heap_base;
extern uint8_t *mask_buffer;    /* shares its address with restart_address, which menu_boot sets to its own address: the original blits into the (finished) boot code */
extern uint16_t palette_dirty;
extern volatile uint16_t vbl_saturating;
extern volatile uint16_t vbl_count;
extern volatile uint32_t pending_request;
extern volatile uint8_t key_down[128];
extern uint8_t *ptr_0cc6;
#endif

#endif
